<?php
require_once '../conexao.php';require_once '../includes/rbac.php';require_once '../includes/flash.php';exigirCargo(['diretor']);
$perms=['agenda_ver'=>'Ver agenda geral','agenda_criar'=>'Criar consultas','agenda_cancelar'=>'Cancelar consultas','pacientes_ver'=>'Ver pacientes','profissionais_gerir'=>'Gerir profissionais','horarios_gerir'=>'Gerir horários','relatorios_ver'=>'Ver relatórios','usuarios_gerir'=>'Gerir usuários'];
if($_SERVER['REQUEST_METHOD']==='POST'){$nome=trim($_POST['nome']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$senha=$_POST['senha']??'';$cargo=$_POST['cargo']??'';$pid=($_POST['profissional_id']??'')!==''?(int)$_POST['profissional_id']:null;$sel=$_POST['permissoes']??[];$valid=['diretor','administrador','recepcionista','profissional'];if(mb_strlen($nome)<3||!$email||!in_array($cargo,$valid,true))flash('error','Preencha nome, e-mail e cargo corretamente.');elseif(!preg_match('/^(?=.*\d)(?=.*[^A-Za-z0-9]).{8,}$/',$senha))flash('error','A senha precisa ter no mínimo 8 caracteres, 1 número e 1 caractere especial.');elseif($cargo==='profissional'&&!$pid)flash('error','Vincule o usuário profissional a um profissional cadastrado.');else try{$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO usuarios(nome,email,senha,cargo,profissional_id,ativo) VALUES(?,?,?,?,?,1)');$s->execute([$nome,$email,password_hash($senha,PASSWORD_DEFAULT),$cargo,$pid]);$uid=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO usuario_permissoes(usuario_id,permissao) VALUES(?,?)');foreach($sel as $p)if(isset($perms[$p]))$ins->execute([$uid,$p]);$pdo->commit();flash('success','Usuário criado com sucesso.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error','Não foi possível criar o usuário. Verifique se o e-mail já existe.');}header('Location: usuarios.php');exit;}
$usuarios=$pdo->query('SELECT u.id,u.nome,u.email,u.cargo,u.ativo,p.nome profissional FROM usuarios u LEFT JOIN profissionais p ON p.id=u.profissional_id ORDER BY u.nome')->fetchAll();$prof=$pdo->query('SELECT id,nome FROM profissionais WHERE ativo=1 ORDER BY nome')->fetchAll();
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Usuários | Aura</title><link rel="stylesheet" href="../css/style.css"></head><body><div class="app-shell"><aside class="sidebar"><a class="side-logo" href="index.php"><img src="../img/logo-aura-oficial.png"></a><small>DIRETORIA</small><a href="index.php">Dashboard</a><a class="active" href="usuarios.php">Usuários e acessos</a><a href="relatorios.php">Consultas / planilha</a><a href="../logout.php">Sair</a></aside><main class="dashboard"><div class="dash-head"><div><p class="eyebrow">CONTROLE DE ACESSO</p><h1>Usuários</h1><p class="muted">Cargos e permissões no estilo RBAC.</p></div></div><?php mostrarFlash();?><details class="dash-card" open><summary><b>+ Adicionar usuário</b></summary><form method="post" class="form-grid"><label>Nome<input name="nome" required></label><label>E-mail<input type="email" name="email" required></label><label>Senha<input type="password" name="senha" minlength="8" required><small>Mínimo 8 caracteres, 1 número e 1 especial.</small></label><label>Cargo<select name="cargo" id="cargo" required><option value="">Selecione</option><option value="diretor">Diretor / Administrador total</option><option value="administrador">Administrador</option><option value="recepcionista">Recepcionista</option><option value="profissional">Profissional</option></select></label><label id="vinculoProf">Vincular profissional<select name="profissional_id"><option value="">Selecione</option><?php foreach($prof as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['nome'])?></option><?php endforeach;?></select></label><fieldset class="permissions"><legend>Permissões específicas</legend><?php foreach($perms as $k=>$v):?><label><input type="checkbox" name="permissoes[]" value="<?=$k?>"> <?=$v?></label><?php endforeach;?></fieldset><button class="btn">Criar usuário</button></form></details><div class="table-wrapper"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Cargo</th><th>Vínculo</th><th>Status</th></tr></thead><tbody><?php foreach($usuarios as $u):?><tr><td><?=htmlspecialchars($u['nome'])?></td><td><?=htmlspecialchars($u['email'])?></td><td><?=ucfirst($u['cargo'])?></td><td><?=htmlspecialchars($u['profissional']??'—')?></td><td><?=$u['ativo']?'Ativo':'Inativo'?></td></tr><?php endforeach;?></tbody></table></div></main></div><script src="../js/app.js"></script></body></html>
